namespace emon;


public static class Aligntest {
    internal static int AtCode(emon.Port.Cells al, int n) {
        // The code of the verdict on the n rows from row 0, 0 when it is below `align-min` or none.
        int v = Align.AlJudge(al, 0, n);
        if (Align.AlConf(v) < Align.AlMin()) {
            return 0;
        }
        return Align.AlCode(v);
    }
    [Xunit.Fact]
    public static void TestEveryRowOfTheTable() {
        emon.Port.Cells al = emon.Port.NewCells();
        // justify: four lines flush at both edges (a hair off), the last flush at the start and short.
        Align.AlLine(al, 0, 40, 1000, 0);
        Align.AlLine(al, 20, 0, 1000, 0);
        Align.AlLine(al, 0, 30, 1000, 0);
        Align.AlLine(al, 10, 5400, 1000, 0);
        emon.Testport.AssertEq(AtCode(al, 4), Model.AlJustify(), "justify");
        emon.Port.CellsDrop(al, 0);
        // start: every S at the edge, the end edge ragged.
        Align.AlLine(al, 0, 1500, 1000, 0);
        Align.AlLine(al, 0, 800, 1000, 0);
        Align.AlLine(al, 0, 3000, 1000, 0);
        Align.AlLine(al, 0, 6000, 1000, 0);
        emon.Testport.AssertEq(AtCode(al, 4), Model.AlStart(), "start");
        emon.Port.CellsDrop(al, 0);
        // end: every E at the edge, the start edge ragged.
        Align.AlLine(al, 1500, 0, 1000, 0);
        Align.AlLine(al, 800, 0, 1000, 0);
        Align.AlLine(al, 3000, 0, 1000, 0);
        Align.AlLine(al, 600, 0, 1000, 0);
        emon.Testport.AssertEq(AtCode(al, 4), Model.AlEnd(), "end");
        emon.Port.CellsDrop(al, 0);
        // center: S = E on every line, and the lines differ.
        Align.AlLine(al, 1000, 1000, 1000, 0);
        Align.AlLine(al, 2500, 2500, 1000, 0);
        Align.AlLine(al, 500, 500, 1000, 0);
        Align.AlLine(al, 3000, 3100, 1000, 0);
        emon.Testport.AssertEq(AtCode(al, 4), Model.AlCenter(), "center");
        emon.Port.CellsDrop(al, 0);
        // a first-line indent comes out of line 1's S: the block is start, not none.
        Align.AlLine(al, 1500, 1800, 1000, 0);
        Align.AlLine(al, 0, 900, 1000, 0);
        Align.AlLine(al, 0, 2600, 1000, 0);
        Align.AlLine(al, 0, 5000, 1000, 0);
        emon.Testport.AssertEq(AtCode(al, 4), Model.AlStart(), "an indented first line");
        emon.Port.CellsDrop(al, 0);
        // a justified block with an indented first line is justify.
        Align.AlLine(al, 1500, 0, 1000, 0);
        Align.AlLine(al, 0, 0, 1000, 0);
        Align.AlLine(al, 0, 0, 1000, 0);
        Align.AlLine(al, 0, 4000, 1000, 0);
        emon.Testport.AssertEq(AtCode(al, 4), Model.AlJustify(), "justify with an indent");
    }
    [Xunit.Fact]
    public static void TestWhatHasNoVerdict() {
        emon.Port.Cells al = emon.Port.NewCells();
        // Two lines, both flush at both edges: not enough to say justify (one non-last line), and not start, end or center.
        Align.AlLine(al, 0, 0, 1000, 0);
        Align.AlLine(al, 0, 4000, 1000, 0);
        emon.Testport.AssertEq(AtCode(al, 2), 0, "two lines");
        emon.Port.CellsDrop(al, 0);
        // A block that wanders: S and E both vary, S - E does not hold.
        Align.AlLine(al, 0, 3000, 1000, 0);
        Align.AlLine(al, 2000, 100, 1000, 0);
        Align.AlLine(al, 700, 4000, 1000, 0);
        Align.AlLine(al, 0, 100, 1000, 0);
        emon.Testport.AssertEq(AtCode(al, 4), 0, "no pattern");
        emon.Port.CellsDrop(al, 0);
        emon.Testport.AssertEq(Align.AlJudge(al, 0, 0), 0, "no lines");
    }
    [Xunit.Fact]
    public static void TestASingleLine() {
        emon.Port.Cells al = emon.Port.NewCells();
        // Centred: S and E at least four t, and within t of each other.
        Align.AlLine(al, 5000, 5100, 1000, 0);
        emon.Testport.AssertEq(AtCode(al, 1), Model.AlCenter(), "a centred line");
        emon.Port.CellsDrop(al, 0);
        // At the end edge, started two body sizes in.
        Align.AlLine(al, 9000, 0, 1000, 0);
        emon.Testport.AssertEq(AtCode(al, 1), Model.AlEnd(), "a line at the end edge");
        emon.Port.CellsDrop(al, 0);
        // At the end edge but started only a body size in: an indented line that happens to fill its row.
        Align.AlLine(al, 1200, 0, 1000, 0);
        emon.Testport.AssertEq(AtCode(al, 1), 0, "an indented full line is not right-aligned");
        emon.Port.CellsDrop(al, 0);
        // Flush at the start: `start`, but below `align-min`, for the second pass (the class) to decide.
        Align.AlLine(al, 0, 5000, 1000, 0);
        emon.Testport.AssertEq(Align.AlCode(Align.AlJudge(al, 0, 1)), Model.AlStart(), "a flush-start line, tentatively start");
        emon.Testport.AssertEq(AtCode(al, 1), 0, "and not written on its own");
    }
    [Xunit.Fact]
    public static void TestTheSecondPassFollowsTheStyleClass() {
        emon.Port.Cells al = emon.Port.NewCells();
        emon.Port.Cells cl = emon.Port.NewCells();
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        Model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout);
        // Block 1: a start block of 4 lines in the 10 pt class; block 2: a single flush-start line of the same class
        // (start, it follows its peers); block 3: a single flush-start line of 20 pt, a class with no multi-line block
        // (a heading: start); block 4: a justified block of 4 lines in the 9 pt bold class and block 5 a single
        // flush-start line of that class (the last line of a justified block, perhaps: none); block 6: a centred line.
        int b1 = Model.NodeNew(nodes, Model.NkParagraph(), 0);
        int b2 = Model.NodeNew(nodes, Model.NkParagraph(), 0);
        int b3 = Model.NodeNew(nodes, Model.NkParagraph(), 0);
        int b4 = Model.NodeNew(nodes, Model.NkParagraph(), 0);
        int b5 = Model.NodeNew(nodes, Model.NkParagraph(), 0);
        int b6 = Model.NodeNew(nodes, Model.NkParagraph(), 0);
        Align.AlLine(al, 0, 1500, 1000, 0);
        Align.AlLine(al, 0, 800, 1000, 0);
        Align.AlLine(al, 0, 3000, 1000, 0);
        Align.AlLine(al, 0, 6000, 1000, 0);
        Align.AlMark(al, b1);
        Align.AlLine(al, 0, 4000, 1000, 0);
        Align.AlMark(al, b2);
        Align.AlLine(al, 0, 4000, 2000, 0);
        Align.AlMark(al, b3);
        Align.AlLine(al, 0, 40, 900, 1);
        Align.AlLine(al, 20, 0, 900, 1);
        Align.AlLine(al, 0, 30, 900, 1);
        Align.AlLine(al, 10, 5400, 900, 1);
        Align.AlMark(al, b4);
        Align.AlLine(al, 0, 4000, 900, 1);
        Align.AlMark(al, b5);
        Align.AlLine(al, 5000, 5100, 1000, 0);
        Align.AlMark(al, b6);
        emon.Testport.AssertEq(Align.AlPass(nodes, attrs, al, cl), 5, "five blocks got an align");
        emon.Testport.AssertEq(Model.NodeSub(nodes, b1), Model.AlStart(), "the multi-line start block");
        emon.Testport.AssertEq(Model.NodeSub(nodes, b2), Model.AlStart(), "a single line follows a class of start blocks");
        emon.Testport.AssertEq(Model.NodeSub(nodes, b3), Model.AlStart(), "a single line in a class with no multi-line block");
        emon.Testport.AssertEq(Model.NodeSub(nodes, b4), Model.AlJustify(), "the justified block");
        emon.Testport.AssertEq(Model.NodeSub(nodes, b5), 0, "a single line in a class of justified blocks gets none");
        emon.Testport.AssertEq(Model.NodeSub(nodes, b6), Model.AlCenter(), "a centred line");
    }
}
